INSERT INTO `pages` VALUES
(1,1,'मानव विकास र याक्थुङ लिम्बुको इतिहास','about','media/2026/01/hq720.jpg','<p>मानव विकास लाखौँ वर्षअघि अफ्रिकाबाट सुरु भएको एक निरन्तर जैविक र सांस्कृतिक परिवर्तनको प्रक्रिया हो, जसले अस्ट्रेलोपिथेकस जस्ता प्रारम्भिक पूर्वजहरूदेखि होमो हाबिलिस, होमो इरेक्टस हुँदै आजका आधुनिक Homo sapiens सम्म विकसित गरायो। सोच, भाषा, औजार प्रयोग, कृषि र सभ्यताको उदयले मानिसलाई पृथ्वीको सबैभन्दा उन्नत जीव बनायो। मानव सभ्यताका विभिन्न जाति र समुदायहरूमध्ये याक्थुङ वा लिम्बूहरू नेपालको पूर्वी पहाडी क्षेत्रमा बसोबास गर्ने प्राचीन किराँत सभ्यताका सन्तान हुन्। उनीहरूको इतिहास करिब तीन हजार वर्षभन्दा पुरानो मानिन्छ, जहाँ समुदायले आफ्नै शासन प्रणाली, संस्कृति र किपट नामक विशिष्ट भूमिसम्बन्धी परम्परा कायम राखेको थियो। याक्थुङहरूको सिरिजङ्गा लिपि, पेयाङ्ग&ndash;युमासाम धर्म, चासोक ताङनाम जस्ता चाड, तथा मौलिक भाषा&ndash;गीत&ndash;नृत्य उनीहरूको पहिचानका मूल आधार हुन्। गोरखा&ndash;लिम्बुवान सम्झौतापछि लिम्बूहरू नेपाल राज्यमा समावेश भए पनि उनीहरूको सांस्कृतिक पहिचान आजसम्म जीवित छ, जसले मानव सभ्यताको विविधता र समृद्ध ऐतिहासिक यात्रा झल्काउँछ।</p>\n<p>&nbsp;</p>\n<h1 data-start=\"157\" data-end=\"209\">🧬&nbsp;<strong data-start=\"162\" data-end=\"209\">१. मानव विकास (Human Evolution &ndash; मानव विकस)</strong></h1>\n<p data-start=\"211\" data-end=\"364\">मानव विकास लाखौँ वर्षसम्म बिस्तारै&ndash;बिस्तारै भएको प्राकृतिक प्रक्रियालाई जनाउँछ। आधुनिक मानव&nbsp;<em data-start=\"303\" data-end=\"317\">Homo sapiens</em>&nbsp;आजको रूपमा आउनुअघि धेरै चरणहरूबाट गुज्रिएको छ।</p>\n<h3 data-start=\"366\" data-end=\"403\">🌍&nbsp;<strong data-start=\"373\" data-end=\"403\">मानव विकासका प्रमुख चरणहरू</strong></h3>\n<h4 data-start=\"405\" data-end=\"478\"><strong data-start=\"410\" data-end=\"478\">(१) Australopithecus (अस्ट्रेलोपिथेकस) &ndash; ४ देखि २ मिलियन वर्षअघि</strong></h4>\n<ul data-start=\"479\" data-end=\"635\">\n<li data-start=\"479\" data-end=\"515\">\n<p data-start=\"481\" data-end=\"515\">यो मानव&ndash;पूर्वज जस्तै प्रजाति थियो।</p>\n</li>\n<li data-start=\"516\" data-end=\"560\">\n<p data-start=\"518\" data-end=\"560\">दुई खुट्टाले हिँड्थ्यो तर दिमाग सानो थियो।</p>\n</li>\n<li data-start=\"561\" data-end=\"635\">\n<p data-start=\"563\" data-end=\"635\">अफ्रिकामा फेला परेका जीवाश्महरूले यस प्रजातिको अस्तित्व प्रमाणित गर्छन्।</p>\n</li>\n</ul>\n<h4 data-start=\"637\" data-end=\"683\"><strong data-start=\"642\" data-end=\"683\">(२) Homo habilis &ndash; २.4 मिलियन वर्षअघि</strong></h4>\n<ul data-start=\"684\" data-end=\"784\">\n<li data-start=\"684\" data-end=\"739\">\n<p data-start=\"686\" data-end=\"739\">&ldquo;Tool man&rdquo; भनिन्छ किनकि पहिलो पटक ढुंगाका औजार बनायो।</p>\n</li>\n<li data-start=\"740\" data-end=\"784\">\n<p data-start=\"742\" data-end=\"784\">दिमाग केही ठुलो र सोच्ने क्षमता बढ्दै गयो।</p>\n</li>\n</ul>\n<h4 data-start=\"786\" data-end=\"832\"><strong data-start=\"791\" data-end=\"832\">(३) Homo erectus &ndash; १.8 मिलियन वर्षअघि</strong></h4>\n<ul data-start=\"833\" data-end=\"939\">\n<li data-start=\"833\" data-end=\"881\">\n<p data-start=\"835\" data-end=\"881\">आफ्रिकाबाट बाहिर निस्किएको पहिलो मानव प्रजाति।</p>\n</li>\n<li data-start=\"882\" data-end=\"939\">\n<p data-start=\"884\" data-end=\"939\">आगो प्रयोग, समूहमा बस्ने, शिकार गर्ने क्षमता विकास भयो।</p>\n</li>\n</ul>\n<h4 data-start=\"941\" data-end=\"1000\"><strong data-start=\"946\" data-end=\"1000\">(४) Neanderthals (निएन्डरथल) &ndash; ४० हजार वर्षअघिसम्म</strong></h4>\n<ul data-start=\"1001\" data-end=\"1080\">\n<li data-start=\"1001\" data-end=\"1047\">\n<p data-start=\"1003\" data-end=\"1047\">अत्यन्त बलियो शरीर, चिसो मौसममा बस्ने योग्य।</p>\n</li>\n<li data-start=\"1048\" data-end=\"1080\">\n<p data-start=\"1050\" data-end=\"1080\">युरोप र पश्चिम एशियामा बसोबास।</p>\n</li>\n</ul>\n<h4 data-start=\"1082\" data-end=\"1125\"><strong data-start=\"1087\" data-end=\"1125\">(५) Homo sapiens &ndash; 300,000 वर्षअघि</strong></h4>\n<ul data-start=\"1126\" data-end=\"1256\">\n<li data-start=\"1126\" data-end=\"1146\">\n<p data-start=\"1128\" data-end=\"1146\">आजका आधुनिक मानिस।</p>\n</li>\n<li data-start=\"1147\" data-end=\"1202\">\n<p data-start=\"1149\" data-end=\"1202\">भाषा, संस्कृति, कला, कृषि, राज्य व्यवस्था विकसित भयो।</p>\n</li>\n<li data-start=\"1203\" data-end=\"1256\">\n<p data-start=\"1205\" data-end=\"1256\">आज संसारभर फैलिएका सबै मानव&nbsp;<em data-start=\"1233\" data-end=\"1247\">Homo sapiens</em>&nbsp;नै हुन्।</p>\n</li>\n</ul>\n<hr data-start=\"1258\" data-end=\"1261\">\n<h1 data-start=\"1263\" data-end=\"1327\">🏞️&nbsp;<strong data-start=\"1269\" data-end=\"1327\">२. याक्थुङ लिम्बुको इतिहास (History of Yakthung Limbu)</strong></h1>\n<p data-start=\"1329\" data-end=\"1552\"><strong data-start=\"1329\" data-end=\"1353\">याक्थुङ वा लिम्बूहरू</strong>&nbsp;नेपालको पूर्वी पहाड (किराँत क्षेत्र) &mdash; विशेषगरी&nbsp;<strong data-start=\"1402\" data-end=\"1453\">पाँचथर, ताप्लेजुङ, तेह्रथुम, धनकुटा, झापा, इलाम</strong>&nbsp;आदि क्षेत्रमा बसोबास गर्ने आदिवासी जनजाति हुन्। उनीहरूको पहिचान, सभ्यता र इतिहास अत्यन्त पुरानो छ।</p>\n<hr data-start=\"1554\" data-end=\"1557\">\n<h2 data-start=\"1559\" data-end=\"1591\">🏔️&nbsp;<strong data-start=\"1566\" data-end=\"1591\">(१) उत्पत्ति र पहिचान</strong></h2>\n<ul data-start=\"1592\" data-end=\"1835\">\n<li data-start=\"1592\" data-end=\"1725\">\n<p data-start=\"1594\" data-end=\"1725\">लिम्बूहरूले आफूलाई&nbsp;<strong data-start=\"1613\" data-end=\"1624\">याक्थुङ</strong>&nbsp;भन्छन्, जसको अर्थ &mdash;&nbsp;<em data-start=\"1645\" data-end=\"1659\">पहाडका मानिस</em>,&nbsp;<em data-start=\"1661\" data-end=\"1673\">लडाकू जाति</em>, वा&nbsp;<em data-start=\"1678\" data-end=\"1716\">धार्मिक/सांस्कृतिक गोत्रयुक्त समुदाय</em>&nbsp;मानिन्छ।</p>\n</li>\n<li data-start=\"1726\" data-end=\"1776\">\n<p data-start=\"1728\" data-end=\"1776\">उनीहरू&nbsp;<strong data-start=\"1735\" data-end=\"1752\">किराँत सभ्यता</strong>का मूल सन्तान मानिन्छन्।</p>\n</li>\n<li data-start=\"1777\" data-end=\"1835\">\n<p data-start=\"1779\" data-end=\"1835\">लिम्बूहरूको आफ्नै&nbsp;<strong data-start=\"1797\" data-end=\"1832\">याक्थुङ चुम्बोङ (गोत्र प्रणाली)</strong>&nbsp;छ।</p>\n</li>\n</ul>\n<hr data-start=\"1837\" data-end=\"1840\">\n<h2 data-start=\"1842\" data-end=\"1870\">📚&nbsp;<strong data-start=\"1848\" data-end=\"1870\">(२) प्राचीन इतिहास</strong></h2>\n<ul data-start=\"1871\" data-end=\"2101\">\n<li data-start=\"1871\" data-end=\"1937\">\n<p data-start=\"1873\" data-end=\"1937\">किराँत&ndash;लिम्बूहरूको इतिहास&nbsp;<strong data-start=\"1899\" data-end=\"1928\">३००० वर्षभन्दा पनि पुरानो</strong>&nbsp;मानिन्छ।</p>\n</li>\n<li data-start=\"1938\" data-end=\"2010\">\n<p data-start=\"1940\" data-end=\"2010\">लिम्बूहरूको राज्यलाई&nbsp;<strong data-start=\"1961\" data-end=\"1982\">याक्थुङ लाहन/लाउङ</strong>&nbsp;वा&nbsp;<strong data-start=\"1986\" data-end=\"1999\">मोरङ राजय</strong>&nbsp;भनिन्थ्यो।</p>\n</li>\n<li data-start=\"2011\" data-end=\"2101\">\n<p data-start=\"2013\" data-end=\"2101\">लिम्बूहरू स्थानीय राजा (सुवा, हाङ, साम्बा) द्वारा संचालित स्वशासित समुदायमा बस्ने गर्थे।</p>\n</li>\n</ul>\n<hr data-start=\"2103\" data-end=\"2106\">\n<h2 data-start=\"2108\" data-end=\"2153\">⚔️&nbsp;<strong data-start=\"2114\" data-end=\"2153\">(३) 1774&ndash;1779 को गोरखा&ndash;लिम्बू युद्ध</strong></h2>\n<ul data-start=\"2154\" data-end=\"2576\">\n<li data-start=\"2154\" data-end=\"2244\">\n<p data-start=\"2156\" data-end=\"2244\">पृथ्वीनारायण शाहले नेपाल एकीकरण शुरू गरेपछि पूर्व किराँत क्षेत्र पनि नेपालमा समावेश भयो।</p>\n</li>\n<li data-start=\"2245\" data-end=\"2362\">\n<p data-start=\"2247\" data-end=\"2362\">लिम्बूहरूलाई बहादुर र शक्तिशाली मानिन्थ्यो, त्यसैले उनीहरू &ldquo;<strong data-start=\"2307\" data-end=\"2319\">खम्बुवान</strong>&rdquo; (Limbuwan) क्षेत्रको शक्तिशाली राज्य थिए।</p>\n</li>\n<li data-start=\"2363\" data-end=\"2576\">\n<p data-start=\"2365\" data-end=\"2437\">लामो युद्धपछि लिम्बूहरूसँग&nbsp;<strong data-start=\"2392\" data-end=\"2427\">सन्धि (लिम्बुवान&ndash;गोरखा सम्झौता)</strong>&nbsp;भयो जसमा:</p>\n<ul data-start=\"2440\" data-end=\"2576\">\n<li data-start=\"2440\" data-end=\"2525\">\n<p data-start=\"2442\" data-end=\"2525\">लिम्बूहरूको&nbsp;<strong data-start=\"2454\" data-end=\"2470\">खुटिया&ndash;नक्वा</strong>&nbsp;नामक सामुदायिक भूमिसम्बन्धी हक (Kipat system) जोगाइयो।</p>\n</li>\n<li data-start=\"2528\" data-end=\"2576\">\n<p data-start=\"2530\" data-end=\"2576\">आफ्नो परम्परा, भाषा, प्रथामा स्वायत्तता दिइयो।</p>\n</li>\n</ul>\n</li>\n</ul>\n<hr data-start=\"2578\" data-end=\"2581\">\n<h2 data-start=\"2583\" data-end=\"2629\">📜&nbsp;<strong data-start=\"2589\" data-end=\"2629\">(४) किपट प्रणाली (Kipat Land System)</strong></h2>\n<ul data-start=\"2630\" data-end=\"2812\">\n<li data-start=\"2630\" data-end=\"2676\">\n<p data-start=\"2632\" data-end=\"2676\">लिम्बूहरूको परम्परागत भूमिसम्बन्धी व्यवस्था।</p>\n</li>\n<li data-start=\"2677\" data-end=\"2729\">\n<p data-start=\"2679\" data-end=\"2729\">जमिन समुदायको साझा सम्पत्ति &ndash; बेचबिखन गर्न नपाइने।</p>\n</li>\n<li data-start=\"2730\" data-end=\"2812\">\n<p data-start=\"2732\" data-end=\"2812\">1960 पछि राज्यले यो व्यवस्था हटायो, जसले धेरै लिम्बूहरूले आफ्नो किपट जमिन गुमाए।</p>\n</li>\n</ul>\n<hr data-start=\"2814\" data-end=\"2817\">\n<h2 data-start=\"2819\" data-end=\"2857\">🎭&nbsp;<strong data-start=\"2825\" data-end=\"2857\">(५) संस्कृति, भाषा र परम्परा</strong></h2>\n<h3 data-start=\"2858\" data-end=\"2872\">✨&nbsp;<strong data-start=\"2864\" data-end=\"2872\">भाषा</strong></h3>\n<ul data-start=\"2873\" data-end=\"3037\">\n<li data-start=\"2873\" data-end=\"2947\">\n<p data-start=\"2875\" data-end=\"2947\">लिम्बूहरूको भाषा&nbsp;<strong data-start=\"2892\" data-end=\"2925\">याक्थुङ पेया (Limbu language)</strong>&ndash; किराँती शाखाको भाषा।</p>\n</li>\n<li data-start=\"2948\" data-end=\"3037\">\n<p data-start=\"2950\" data-end=\"3037\">आफ्नो&nbsp;<strong data-start=\"2956\" data-end=\"2974\">सिरिजङ्गा लिपि</strong>&nbsp;छ, जुन तेन्जिङ हाङ लिम्बू (सिरिजङ्गा) ले पुनर्जीवित गरेका थिए।</p>\n</li>\n</ul>\n<h3 data-start=\"3039\" data-end=\"3063\">✨&nbsp;<strong data-start=\"3045\" data-end=\"3063\">धर्म र विश्वास</strong></h3>\n<ul data-start=\"3064\" data-end=\"3181\">\n<li data-start=\"3064\" data-end=\"3117\">\n<p data-start=\"3066\" data-end=\"3117\">परम्परागत धर्म:&nbsp;<strong data-start=\"3082\" data-end=\"3102\">केहाम (Khe-Lung)</strong>&nbsp;/&nbsp;<strong data-start=\"3105\" data-end=\"3116\">युमासाम</strong></p>\n</li>\n<li data-start=\"3118\" data-end=\"3181\">\n<p data-start=\"3120\" data-end=\"3181\">प्रकृति पूजा, पुर्खा पूजा, चण्डी&ndash;नाच, युमापोक्तम आदि परम्परा।</p>\n</li>\n</ul>\n<h3 data-start=\"3183\" data-end=\"3207\">✨&nbsp;<strong data-start=\"3189\" data-end=\"3207\">मुख्य संस्कृति</strong></h3>\n<ul data-start=\"3208\" data-end=\"3312\">\n<li data-start=\"3208\" data-end=\"3258\">\n<p data-start=\"3210\" data-end=\"3258\"><strong data-start=\"3210\" data-end=\"3220\">येकेवा</strong>,&nbsp;<strong data-start=\"3222\" data-end=\"3240\">च्यासोक ताङनाम</strong>&nbsp;(मौलिक नयाँ वर्ष)</p>\n</li>\n<li data-start=\"3259\" data-end=\"3275\">\n<p data-start=\"3261\" data-end=\"3275\"><strong data-start=\"3261\" data-end=\"3275\">केहाम पूजा</strong></p>\n</li>\n<li data-start=\"3276\" data-end=\"3312\">\n<p data-start=\"3278\" data-end=\"3312\"><strong data-start=\"3278\" data-end=\"3294\">हाक्पारे गीत</strong>,&nbsp;<strong data-start=\"3296\" data-end=\"3312\">ध्याङ्रो नाच</strong></p>\n</li>\n</ul>\n<hr data-start=\"3314\" data-end=\"3317\">\n<h2 data-start=\"3319\" data-end=\"3347\">🌏&nbsp;<strong data-start=\"3325\" data-end=\"3347\">(६) आजका लिम्बूहरू</strong></h2>\n<ul data-start=\"3348\" data-end=\"3528\">\n<li data-start=\"3348\" data-end=\"3420\">\n<p data-start=\"3350\" data-end=\"3420\">नेपाल, सिक्किम, दार्जिलिङ, आसाम, भूटान, म्यानमार आदि क्षेत्रमा बसोबास।</p>\n</li>\n<li data-start=\"3421\" data-end=\"3468\">\n<p data-start=\"3423\" data-end=\"3468\">शिक्षित, आधुनिक र आफ्नो पहिचान जोगाउन सक्रिय।</p>\n</li>\n<li data-start=\"3469\" data-end=\"3528\">\n<p data-start=\"3471\" data-end=\"3528\">राजनीति, साहित्य, सेना, कला&ndash;संस्कृतिमा महत्वपूर्ण योगदान।</p>\n</li>\n</ul>','published','2026-01-01 15:39:29','2025-11-23 12:56:45','2026-01-01 15:39:29',NULL),
