INSERT INTO `posts` VALUES
(1,1,NULL,1,'आदिलको ब्याटिङमा विराटनगरलाई काठमान्डुले दियो १३५ रनको लक्ष्य',NULL,'aathalka-byatanama-varatanagaralii-kathamanadal-thaya-ranaka-lkashhaya','media/2025/11/aadil.jpg','<p>विराटनगर किंग्सले उत्कृष्ट बलिङ गरेपछि नेपाल प्रिमियर लिग (एनपीएल) मा काठमान्डु गोर्खाज १३४ रनमा रोकिएको छ ।</p>\n<p>कीर्तिपुरस्थित टीयू म&zwnj;ैदानमा विराटनगरले टस जितेर बलिङ रोजेपछि पहिले ब्याटिङ गरेको काठमान्डुले&nbsp; पूरै २० ओभर खेल्दा ७ विकेट गुमाएर १३४ रन बनायो ।</p>',0,0,'published','2025-11-22 11:44:01','2025-11-22 11:39:31','2025-11-22 11:44:01',NULL),
(2,6,NULL,6,'लोेकेश लिबाङ ','अध्यक्ष','lokesh-libang','media/2025/12/lokesh-libang.JPG','<p>lokesh&nbsp;</p>',0,0,'published','2025-12-25 09:54:26','2025-12-25 09:54:26','2025-12-25 09:54:26',NULL),
(3,6,NULL,4,'केत्तकुम लिबाङ पाङ्पत सयङको वंशावली पुस्तक विमोचन कार्यक्रमका झलकहरु',NULL,'katatakama-lbna-panapata-sayanaka-vashaval-pasataka-vamacana-karayakaramaka-jhalkahara','media/2025/12/img-2474.JPG','केत्तकुम लिबाङ पाङ्पत सयङको वंशावली पुस्तक विमोचन कार्यक्रमका झलकहरु ',0,0,'published','2025-12-25 10:33:03','2025-12-25 10:33:03','2025-12-25 10:33:03',NULL),
(4,6,NULL,2,'मुन्धुङ्गे वंशहरुको माङगेन्ना यक साप्तकनेम्बामा पुजा कार्यक्रमका झलकहरु',NULL,'manathhanaga-vashaharaka-managanana-yaka-sapatakanamabma-paja-karayakaramaka-jhalkahara','media/2025/12/img-9543-5-11zon.jpg','<p>मुन्धुङ्गे वंशहरुको माङगेन्ना यक साप्तकनेम्बामा पुजा कार्यक्रमका झलकहरु</p>\n<p>&nbsp;</p>\n<p><img src=\"/storage/media/2025/12/img-0523-2-11zon.jpg\" alt=\"IMG_0523_2_11zon.jpg\"></p>\n<p><img src=\"/storage/media/2025/12/img-0325-1-11zon.jpg\" alt=\"IMG_0325_1_11zon.jpg\"><img src=\"/storage/media/2025/12/img-0325-1-11zon.jpg\" alt=\"IMG_0325_1_11zon.jpg\"></p>\n<p><img src=\"/storage/media/2025/12/img-9008-copy-4-11zon.jpg\" alt=\"IMG_9008 - Copy_4_11zon.jpg\"></p>\n<p><img src=\"/storage/media/2025/12/img-9543-5-11zon.jpg\" alt=\"IMG_9543_5_11zon.jpg\"><img src=\"/storage/media/2025/12/img-9543-5-11zon.jpg\" alt=\"IMG_9543_5_11zon.jpg\"></p>',0,0,'published','2025-12-26 12:27:42','2025-12-26 11:38:52','2025-12-26 12:27:42',NULL),
(5,6,NULL,6,'केत्तकुम लिबाङ पाङ्पत सयङ केन्द्रीय कार्यसमितिको विवरण',NULL,'katatakama-lbna-panapata-sayana-kanatharaya-karayasamataka-vavaranae','media/2025/12/img-2595-optimized-2000.jpg','<p>केत्तकुम लिबाङ पाङ्पत सयङ केन्द्रीय कार्यसमिति<br>१. अध्यक्ष : लोकेन्द्र लिम्बू लोकेश &ndash; मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ&nbsp;<br>२. उपाध्यक्ष : भरत पायल लिम्बू &ndash; सुनसरी<br>३. सचिव : देउ कुमार लिम्बू मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ&nbsp;<br>४. सह&ndash;सचिव : बल बहादुर पाङ्बोहाङ लिम्बू मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ&nbsp;<br>५. कोषाध्यक्ष : लोकमान लिबाङ मैवाखोला &ndash; ६ फाकुम्बा ताप्लेजुङ, हाल काठमाडौं &nbsp;<br>६. सदस्य : मैत बहादुर लिबाङ , फालेलुङ &ndash; ५ प्राङबुङ पाँचथर<br>७. सदस्य : जंगबहादुर लिबाङ मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ&nbsp;<br>८. सदस्य : पुर्ण बहादुर लिबाङ &ndash; मोरङ&nbsp;<br>९. सदस्य : हर्कमान लिबाङ लिम्बू &ndash; आठराई त्रिवेणी &ndash; २ रमिते फुलबारी&nbsp;<br>१०. सदस्य : रन कुमारी लिम्बू । मैवाखोला &ndash; ६ फाकुम्बा ताप्लेजुङ,<br>११. सदस्य : लिबाहाङ पाङ्पत लिबाङ &ndash; संखुवासभा<br>१२. सदस्य : पुर्ण कुमारी लिम्बू &ndash; सुनसरी&nbsp;<br>१३. सदस्य : अमृता श्रेष्ठ लिबाङ मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ&nbsp;<br>केत्तकुम लिबाङ पाङ्पत सयङ केन्द्रीय सल्लाहका समिति<br>१. सल्लाहकार संयोजक श्री डिल्ली प्रसाद पाङ्पत लिबाङ &ndash; विर्तामोड &ndash; १, झापा ।&nbsp;<br>२. सल्लाहकार &nbsp;श्री डम्बर बहादुर पाङ्पत लिबाङ &nbsp;&ndash; तिखेदेवल &ndash; १४, ललितपुर, हाल यु.के ।<br>३. सल्लाहकार &nbsp;श्री डम्बर लिबाङ पाङ्पत लिबाङ &ndash; चारआली &ndash; १२ झापा, हाल ः युएई ।<br>४.सल्लाहकार &nbsp;श्री कुल प्रसाद पाङ्पत लिबाङ &ndash; हात्तिगौंडा &nbsp;&ndash; ७, काठमाडौं हाल ः युके ।<br>५.सल्लाहकार श्री उपेन्द्र पाङ्पत लिबाङ &ndash; धरान &ndash;१६, सुनसरी, हाल, अमेरिका ।<br>६. सल्लाहकार श्री खगेन्द्र पाङ्पत लिबाङ &ndash; सुर्यविनायक &ndash; ५ भक्तपुर, हालः हङकङ ।<br>७. सल्लाहकार श्री बम बहादुर पाङ्पत लिबाङ &ndash; आठराई त्रिवेणी &ndash; २ रमिते फुलबारी, हाल ः युके ।<br>८. सल्लाहकार श्री राजन पाङ्पत लिबाङ &ndash; बराहक्षेत्र &ndash; ९, राजाबाँस सुनसरी ।<br>९.सल्लाहकार &nbsp;श्री इश्वरसिंङ पाङ्पत लिबाङ &ndash; आठराई त्रिवेणी &ndash; २ रमिते फुलबारी, हाल ः युके ।<br>१०. सल्लाहकार श्री बिर बहादुर पाङ्पत लिबाङ &ndash; बराहक्षेत्र &ndash; ७ सुनसरी ।<br>११. सल्लाहकार &nbsp;श्री रबिन्द्र पाङ्पत लिबाङ &ndash; मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ ।<br>१२. सल्लाहकार श्री बलहाङ पाङपत लिबाङ &ndash; मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ ।<br>१३. सल्लाहकार श्री डिक प्रसाद पाङ्पत लिबाङ &ndash; मैवाखोला &ndash; ६ फाकुम्बा ताप्लेजुङ, हाल ः हङकङ ।<br>१४. सल्लाहकार श्री निर बहादुर पाङ्पत लिबाङ &ndash; मिक्वाखोला &ndash; ३ लिबाङ ताप्लेजुङ ।<br>१५. सल्लाहकार श्री दिपक पाङ्पत लिबाङ &ndash; बराहक्षेत्र &ndash; ९, राजाबाँस सुनसरी ।<br>१६. सल्लाहकार श्री शरण कुमार पाङ्पत लिबाङ, आठराई त्रिवेणी &ndash; २ रमिते फुलवारी ताप्लेजुङ ।</p>',0,0,'published','2025-12-31 15:51:58','2025-12-31 15:51:58','2025-12-31 15:51:58',NULL),
(6,6,NULL,3,'“वंश, इतिहास र संस्कृतिको अमूल्य दस्तावेज”पाङ्पत लिबाङ वंशावली” -  “बैरागी काइँला”',NULL,'vasha-itahasa-ra-sasakataka-amalya-thasatavajapanapata-lbna-vashaval-braga-kail','media/2025/12/bairagi-kainla-copy.jpg','<p>&ldquo;इतिहास सुरक्षित गर्ने अनुकरणीय कृति&rdquo;<br>शुभकामना<br>समयको लामो कालखण्डमा आफ्नो कुलवंशको इतिहास विलुप्त भएर जाँदा हुने अपूरणीय क्षतिको थोरै भएपनि शोधभर्नाका लागि &nbsp;हाल आएर याक्थुङ &nbsp;लिम्बूजातिमा आ&ndash;आफ्ना कुलवंशको वंशावली तयार गर्ने अनुकरणीय लहर चलेको छ ।<br>हामी को हौँ, कहाँबाट वर्तमान अवस्थलमा आईपुग्यौँ भन्ने प्रश्नको उत्तरको खोजीगर्दा आफ्नो कुलवंश र परिवारको उद्गमस्थल (माङगेन्ना यक) सम्म आइपुगेका छौँ । त्यसो त छोटकरी रुपमा भएपनि बुढापाकाले मौखिकरुपमा यी कुरा भन्दै ल्याएका पनि हुन् । हाम्रा फेदाङमाहरुले माङगेन्ना पूजा गर्दा पनि सकेसम्म जाने जति वंशावलीको विवरण दिने गरेका छन् । तर ती पर्याप्त नहुँदा विस्तृतरुपमा वंशवलीझैँ ऐतिहासिक दस्तावेजको निर्माणको आवश्यकता हुन्छ ।<br>यसै सन्दर्भमा मुधुङगेवंश्ी ४ भाइ लिबाङहरु, जस्तैः पाङ्पत लिबाङ,लुङ्खिम्बा लिबाङ, फेम्सङ लिबाङ र नैदेम्बा लिबाङभित्रको लुङ्खिम्बा लिबाङले यसअघि नै वंशावली प्रकाशन गरिसकेका छन् भने यसपटक &nbsp;पाङ्पत लिबाङले &nbsp;पनि आफ्नो वंशावली प्रकाशन गर्न लागेको देख्दा मलाई अत्यन्त हर्ष लागेको छ । देशभित्र र देशबाहिर बसोबास गर्ने पाङ्पत लिबाङ याक्थुङ लिम्बूहरुको यो वंशावली एउटा ऐतिहासिक दस्तावेज हो । यो वंशावली मात्र नभएर यसको महत्व यसभित्र समाहित सामाग्रीहरु, जस्तैः मानवसृष्टिदेखि आजसम्म भएका घटनाहरुको विवरणसहित मुधुङगेवंशीको उद्गम &nbsp;र इतिहास, तिनले पालन गरिल्याएका &nbsp;सामाजिक, सांस्कृतिक र धार्मिक रीतिथिति र संस्कार आदिको विस्तृत विवरणले पनि यो पाङ्पत लिबाङ वंशावलीको महत्व धेरै बढाएको छ । &nbsp;<br>पाङ्पत लिबाङ वंशावलीको रुपमा अत्यन्त महत्वपूर्ण ग्रन्थ तयार गर्नु भएकामा सबै &nbsp;पाङ्पत लिबाङ दाजुभाइलाई बधाईका साथ धन्यवाद दिँदै तपाईँहरुको सराहनीय कामको सफलताको शुभकामना गर्दछु ।<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</p>\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; तिल बिक्रम नेम्बाङ &nbsp;&ldquo;बैरागी काइँला&rdquo;<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;कुलपति<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; नेपाल प्रज्ञा प्रतिष्ठान</p>',0,0,'published','2025-12-31 16:29:29','2025-12-31 16:29:29','2025-12-31 16:29:29',NULL),
(7,6,NULL,3,'डम्बरध्वोज पाङ्पत लिबाङको जीवनी',NULL,'raja-damabrathhavaja-panapata-lbnaka-javana','media/2026/01/photo123.png','<p>लिबाङ्गे राजा डम्बरध्वोज पाङ्पत लिबाङको संक्षिप्त जीवनी</p>\n<p>✍️गोबाहाङ लिबाङ &ldquo;सेवालुङ&rdquo;</p>\n<p>मिक्वाखोला गड्तिर मास्तिर एउटा उर्वर जमिनमा हाम्रा आदिम पुर्खा मुन्धुङ्गेले लिबाङ जातिको सभ्यताको सुरुवात गरे । हाल आएर विभिन्न ठाउँहरुमा फैलिएर लिबाङ जातिहरु पुगेका छन् तर जहाँ पुगे पनि हाम्रा पुर्खाहरुले सभ्यताको पहिलो बास बसेको ठाउँ लिबाङको साप्तकनेम्बा हो । यसरी मुन्धुङगेको सन्तानहरु फैलिँदै जाने क्रममा वि.स. १९३१ सालको कार्तिक महिनाको यम पन्चकको दिन डम्वरध्वोज पाङ्पत लिवाङको जन्म भएको थियो । उनी राणाकालका प्रतापि सुब्बा थिए । उनले मेवाखोला थुममा प्रभाव जमाएका थिए । डम्बरध्वोज लिबाङ एक सुर र प्रतापी सुब्बा थिए ।</p>\n<p>सानो होचो कदको भएपनि उनको हाउभाउँ निकै साानदार हुने गथ्र्यो । जो कोही मानिसहरुले उहाँलाई सिधा नजरले हेर्न सक्दैन थिए भन्ने जानकारहरु बताउँछन् । एकपटक डम्बरध्वज लिबाङ ताप्लेजुङवाट लिबाङ फर्किदा देउलिङगे&ndash;दोभान बिचको बाटोमा आफ्नो दलवलसहित तलबाट राणाको ठुलो मान्छे आउँदै थियो । दुवै जना घोडामा थिए । एकले अर्कोलाई बाटो छोड्न भने तर दुवै मानेनन् र झगडा हुन लाग्यो । म राणा हुँ अड्डाको हाकिम भन्यो, डम्वरध्वोजले पनि म लिबाङगे राजा हुँ । यो मेरो ईलाका हो भन्यो । झगडाले उग्र रुप लिने स्थिति देखिएपछि दुवै पक्षको मान्छेले दुवैलाई सम्झाएर झडप हुन पाएन भनिन्छ । राणाले पनि आफ्नो शक्ति पछिवाट लगाएन । डम्वरज्वोज निकै धनि, शक्तिशालि थिए । उनले युवाहरुलाई आफ्नो सुरक्षा दस्ताको रुपमा राखेका थिए । डम्वरध्वोज कसरी शक्तिमा आए भन्ने वारेमा भन्नुपर्दा पालुङवा वंशसग पनि जोडिएको पाईन्छ ।</p>\n<p>तत्कालिन समयमा ताप्लिजुङ साँवानेवा(हाल सिम्ले) मा भर्तमान पालुङवा भन्ने नामि सुव्वा थिए । उनले आफ्नो छोरा धनदलको लिवाङ कुल घरानाको देशमति लिवाङसँग विहे गराएका थिए । भर्तमानको मृत्युपछि धनदल पनि जल्दोबल्दो सुब्बा भए । तर उनको मृत्यु सन्तान गर्भमा हुँदा भएकोले धनदलको भाई खलकले सुवाङगी दावि गरि देशमतिलाई ल्याईते वनाएर (नेपाल) काठमाडौंमा मुद्धा लगाए । देशमतिले आफ्नो माइती लिवाङको पनि सहायता लिईन् । देशमतिले आठ महिनाको गर्भ बोकेर महिनादिन लगाएर नेपाल (काठमाण्डौमा) गएर मुद्दा धाईन् । देशमति डम्वरध्वोज लिवाङको फुपू थिईन् । फुपूको सुव्वाङगीको मुद्दा मामिलाबारे सानैमा डम्बरध्वोजले ज्ञान लिएका थिए । त्यस्तै उनि वयस्क भएको वेलामा पनि फुपूको काम गर्न चैनपुर, नेपाल (काठमाण्डौ) आउने जाने गर्थे । त्यसक्रममा उनि निकै चतुर भइसकेका थिए । जब उनि सुब्बा भए । उनलाई शक्तिशाली हुन मन लाग्यो । ठुलो हुन मन लाग्यो ।</p>\n<p>&nbsp;उनि देश खाई शेष भएकाले अरु भन्दा बाठो भए । उनले धेरै ठाँउमा आफ्नो हैकम जमाए । धन सम्पति र प्रतिष्ठा कमाए । वि.स. १९९५ तिर डम्बरध्वोज लिबाङ उत्तरी प्रशासन ओलाङचुङ गोलाको लप्टन नियुक्त भएर गोला पुग्दा त्यहाँको गोवा भन्ने ठाउँमा राजा जस्तै शासन चलाउँथे । त्यही भएर डम्बरध्वोज लिबाङ तत्कालीन लिबाङगे राजा कहलिएको हो । अन्तत शक्तिशाली लिबाङगे राजा भए । वास्तवमा डम्वरध्वोज सानो कदका मान्छे थिए्, तर निकै वुद्धिमान थिए । उनि त्यो बेलाका मेवाखोला क्षेत्रकै वरिष्ठ व्यक्ति थिए । यसरी डम्बरध्वोज लिबाङले वि.स. १९७० देखि २००९ साल सम्म आफु त्यहाँको राजा घोषणा गरी अड्डा पुलिस सबैको वन्दोवस्त गरी फौजदारी र ज्यान मुद्दा सम्मको सबै मुद्दाहरुको न्याय निसाप गर्दथे । उनले लिवाङ लगायत मेवाखोलाभरिको तत्कालिन ताप्लिजुङको राणाको अड्डाले पनि सम्मान गर्दथ्यो । त्यसैले मध्य राणाकालदेखि राणाकालको अन्त्य वि.स.२००७ साल सम्म पनि उनलाई लिबाङगे राजा भनेर चिनिन्थ्यो । वास्तवमा उनि राजा थिएनन् । तर उपमा पाएका थिए । लिम्वुवानमा धेरै सुब्बाहरु थिए । हैसियत उस्तै हो । तर आफ्नो रवाफले उनि लिबाङगे राजा भएका थिए । यस्ता चतुर साहसी प्रतापी सुब्बा डम्बरध्वोज पाङ्पत लिबाङको ७८ वर्षको उमेरमा वि.स. २००९ सालमा देहान्त भएको थियो । उनको काइला छोरा मान वहादुर पाङ्पत लिवाङ ताप्लेजुङ जिल्ला पञ्चायतको पहिलो सभापति हुन ।</p>\n<p> डम्बरध्वज लिबाङको फुपू देशमति लिबाङ</p>\n<p>ताप्लेजुङको सिम्लेमा सुब्बा धनदल पालुङवा पनि त्यो जमानाका निकै नामि र प्रतापी सुब्बा कहलिएका थिए । धनदलको श्रीमती देशमति डम्बरध्वज लिबाङका पुपू थिइन् । फुपू देशमति लिबाङबाट पनि डम्बरध्वोज लिबाङले धेरै कुराहरु सिक्ने जान्ने मौका पाएका थिए । डम्वरध्वोजको छोराहरु कोहि बर्मामा पुगेर मन्त्री पनि भएका छन् रे भन्ने सुन्नमा आएको थियो । डम्वरध्वोजको बराजु शुभवन्त लिवाङ हुन । शुभवन्त नेपाल एकिकरण अभियानताको तमोर थुमका सुब्बा (हाङ) हुन् । विसं १८४३ तिरका पालुङवादेनको राजा युफत्ताहाङ धनदलको बाजे थिए । युफत्ताहाङ र शुभवन्त लिवाङ समकालिन हुन् । मैवाखोले सुब्बा श्रीदेउराय फागो र सुभवन्त लिबाङहरु समकालीन थिए भनेर रणबहादुर शााहले दिएको १८३९ सालको लालमोहरबाट प्रष्ट हुन्छ । नेपाल एकिरणमा उहाँहरुको निकै महत्वपूर्ण योगदान रहेको पाइन्छ । युफत्ताहाङको छोरा भर्तमान राईगिरि सुब्बा वि.स. १८९१ मा भएका हुन् । धनदल सुव्वा वि.स. १८१८ मा भएका हुन् । सुवाङगि मुद्दा वि.स. १९२५ तिर भएको हो ।</p>\n<p>तर कतिपय कामहरु वि.स. १९५० तिर पनि भएको देखिन्छ ।  डम्बरध्वोज लिबाङले गर्नुभएको शैक्षिक सुरुवात डम्बरध्वोज लिबाङको समयमा नेपालमा एकछत्र जहानिया राणाशासन अन्तर्गत श्री ३ सरकार जुद्धशम्शेर नेपालको प्रधानमन्त्री पदमा आसीन थिए । त्यसताका राणा वंश र उनीहरूको परिवार बाहेक शिक्षादीक्षाको लागि स्कुल जान अन्य मानिस अर्थात सर्वसाधारण जनतालाई प्रतिबन्ध थियो । पाठशालाको निम्ति कुनै स्कुलहरू थिएन । त्यसबेला डम्बरधोज लिवाङले आफ्नो निजी स्रोतमा शिक्षक राखी आफ्नो छोराहरू र गाउँको केही मानिसहरूलाई शिक्षादीक्षा दिन थाले । त्यस समयको लिपि काइते अक्षरमा थियो । त्यो काइते अक्षर आज हामी पढ्न सक्दैनौं । त्यसबेला रसिद लेख्ने तमसुक लेख्ने व्यहोरा सिकाइन्थ्यो र अलिक उच्च शिक्षाको लागि वादी प्रतिवादी लेख्न सिकाउँथे । किनकि त्यो समयमा कुनै मुद्दामामला गर्नुपर्दा अदालतको व्यवस्था भए पनि वकिल चाहिँ थिएनन् । र केही जानिफकार मानिसलाई सिधै न्यायाधीशमा नियुक्त हुने प्रचलन थियो र आफूले मुद्दा दायर गरेपछि त्यो मुद्दाको बहस आफैंले गर्नुपथ्र्यो ।</p>\n<p> डम्बरध्वोज लिबाङको छोरा टेकबहादुर पाङ्पत लिबाङको उदय र अवसान</p>\n<p>एकपटक मुद्दाकै शिलशिलामा डम्बरध्वोज लिवाङको जेठो छोरा टेक बहादुर लिवाङ काठमाडौंको अदालतमा पुगे र उसले आफ्नो मुद्दाको लागि अदालतमा उभिएर बहस गर्न थाले । टेकबहादुर लिवाङले बोलेको शैली तार्किक क्षमता उनले बोलेको कानूनी भाषाहरू अन्य बहसकर्ता भन्दा धेरै तेज र कानुन सम्मत भाषाहरू बोलेको हुनाले नेपालको पूर्वी क्षेत्र ताप्लेजुङ लिबाङको प्रतिभाशाली उदयमान ठिटो त्यो पनि लिम्बूको छोरा जम्माजम्मी उनको उमेर २१&ndash;२२ वर्षको थियो । त्यसरी एउटा लिम्बू ठिटोले अदालतभित्र बहस गरेको भाषा सुनेर अदालतका कर्मचारी र न्यायाधीश, राणाहरू अचम्ममा परे र तत्काल तिनीहरूले टेकबहादुर लिबाङलाई त्यही अदालतमा जागिर दिलाइदिने घोषणा गरे । त्यसपछि डम्बरध्वोज लिवाङ आफ्नो जेठो छोरो टेकबहादुर लिवाङलाई काठमाडौं अदालतमा छोडेर केही साथीहरूको साथ घर फर्के । त्यसबेला भक्तपुर, सिन्धुली, रामेछाप, ओखलढुङ्गा, संखुवासभाको बाटो जाँदा १६ दिन फर्किदा १६ दिन हिँडेर आवतजावत गर्नुपथ्र्यो । डम्बरध्वोज लिबाङ आफ्नो छोरा अदालतको कर्मचारी भए भनेर उनि ढुक्कका साथ लिबाङ फर्किएका थिए ।</p>\n<p>केही समय पछाडी काठमाडांैबाट एउटा चिट्ठी डम्बरध्वोजकोमा आयो, उक्त चिठ्ठी धागोले बाँधिएको थियो । धागोले बाँधिएको चिट्ठी देखेर डम्बरध्वोज लिबाङ आश्चर्यमा परे । चिठ्ठी खोलेर हेर्दा उसको छोरा टेकबहादुर लिबाङ बिरामी भई मृत्यु भएको व्यहोरा लेखेको रहेछ । आफ्नो प्रतिभाशाली छोराको मृत्युको खबर पाउँदा डम्बरध्वोज लिबाङ अति विक्षिप्त अवस्थामा पुगे । अपसोस गर्नुपर्ने विकल्प केही थिएन त्यसबेला सञ्चार माध्यम थिएन् , न यातायातको व्यवस्था नै थियो । स्मरण रहोस् त्यस समयमा मृत्युको खबर अर्थात चिठ्ठी पठाउँदा चिठ्ठीलाई एक फन्को धागोले बेरेर हुलाकमा पठाउने प्रचलन थियो । नियतिको खेल पनि बडो विडम्बनापूर्ण हुँदोरहेछ । एक प्रभावशाली युवा टेकबहादुर लिबाङ आफ्नो कालगतिले मृत्यु भएको होइन् । उनको बौद्धिक दूरदर्शिता देखेर श्री ३ सरकार राजा भोलिको दिन अर्थात भविष्यमा अप्ठ्यारो स्थिति सृृजना गराउँला वा आफ्नो शासनसत्तामा आँच आउँला भनेर षड्यन्त्रपूर्वक टेकबहादुर लिबाङको हत्या गरिएको रहेछ । नेपाली जनतामा सर्वविदितै होला राणाशासनमा ३ कुरा थिए । राणा बाहेकका टाठाबाठाहरूलाई जेल, प्रवास वा मृत्युदण्ड दिइन्थ्यो ।</p>\n<p> डम्बरध्वोज लिबाङको ५२ ढोके दरबार बनाउने योजना</p>\n<p>समयको गतिशीलतासँगै डम्बरध्वोज लिबाङको शासनशक्ति र प्रभाव बढ्दै गयो । एकदिन उसले राती सपनामा ढाँडघारी अर्थात ढुङ्गैढुङ्गा भएको ठाउँ जो अहिले मिक्वाखोला गाँउपालिका &ndash; ३, ( साविक लिबाङ गा.वि.स. वडा न.&ndash; ३) मा पर्छ, त्यो ठाउँमा उसले एउटा दरबार बनाएको सपना देखेछ । जब उनी ब्युँझे त्यही दिनदेखि त्यहीँ ठाउँमा ५२ ढोके दरबार बनाउने इच्छा व्यक्त गरे । अपसोस त्यो ठाउँ ढाँडघारी अर्थात ढुङ्गैढुङ्गा भएकोले त्यसलाई पुर्ने वा व्यवस्थापन गर्न थाले । त्यसरी त्यो ठाउँ पुर्ने क्रमशः २&ndash;३ किलोमिटर टाढा तुक्लिदेन भन्ने ठाउँबाट मान्छे लगाएर चिम्टे माटो ल्याई त्यो ढाँडघारीलाई पुर्ने व्यवस्था गरियो । सयौं मजदुरहरूले दुई वर्ष लगातार खटेर त्यो ठाउँलाई पुरे र त्यहीँ ठाउँमा ५२ वटा ढोका ५२ वटा झ्याल तीनतिर गेट वरिपरि कम्पाउण्ड भएको ५२ ढोके दरबार ५ वर्ष लगाएर निर्माण गरे । त्यसको सम्पूर्ण मेटेरियल अर्थात सामग्रीहरू चौरी घोडा खच्चड प्रयोग गरेर तिब्बतबाट ल्याएर दरबारको निर्माण गरेका थिए ।</p>\n<p>&nbsp;समयको वहावसँगै डम्बरध्वोज लिबाङको प्रभाव बढ्दै गयो । थुम थुमका मानिस वरिपारिका मानिस गाउँभरिका मानिसहरूको उपस्थिति बढ्दै गयो । डम्बरध्वोजको मुख्य विशेषता कुनै मानिस उनको दरबारमा उपस्थित भएकोलाई पेटभरि खुवाएर मात्र पठाउने गर्थे । त्यसको ज्वलन्त उदाहरण थियो ऊ साँच्चिकै पूजा प्रेमी थिए । दशैं तिहारमा राँगा भैंसी खसी बोका काटेर सारा गाउँलेलाई भोज खुवाउने गर्थे ।</p>\n<p> डम्बरध्वोज लिबाङद्वारा लिबाङलाई पृथक राज्य घोषणा</p>\n<p>ताप्लेजुङ जिल्ला मिक्वाखोला &ndash; ३ लिबाङमा वि.स.१९६० देखि १९६५ साल भित्र जम्मा ५ वर्ष लगाएर डम्बरध्वोज लिबाङले ५२ वटा ढोका भएको ५२ ढोके दरबार निर्माण गर्नुभएको थियो । डम्बरध्वोजको एकछत्र शासन दिनानुदिन बढ्दै गयो । श्री ३ सरकारबाट उनलाई उत्तरी प्रशासन ओलाङचुुङ गोलाको लागि लप्टन पदमा पनि नियुक्त गरे । तीन वर्षसम्म आफ्नो पदीय भूमिकालाई कुशलतापूर्वक निर्वाह गरे । आफ्नो सफलतासँगै उनको महत्वकांक्षा पनि बढ्दै गयो । उनले आफू स्वयम राजा रहनेगरी लिबाङमा दरबार रहने, चंङचिपुङमा ठाना, सैधोज लप्टन नानी च्युक्पा तिलिङ्गा, हाङदुरुङ कुरुवा, धुले छिरुवा, दोभान ढुकुवा यी ठाउँहरूलाई सिमाङ्कन गरेर एउटा छुट्टै पृथक राज्यको घोषणा गरेर यसको सम्पूर्ण लेखापढी गरी श्री ३ सरकार काठमाडौंमा जानकारी पत्र पठायो । राणा सरकारमा पत्र प्राप्त हुनासाथ राणा सरकारले धनकुटाबाट ३०० को हाराहारीमा हतियारले सुसंगठित सेना लिबाङमा पठायो । राणा सरकारको आदेशको व्यहोरा यस्तो थियो ।</p>\n<p>पृथक राज्य घोषणा गर्ने डम्बरध्वोज लिवाङको टाउको काटेर काठमाडौं श्री ३ सरकारमा ल्याउने । त्यो आदेश लिएर सेनाको क्याप्टेनको नेतृत्वमा लिबाङ पुगी डम्बरध्वोजको दरबार घेरा हाले । डम्बरध्वोज दरबारभित्र रहेछ । राणा सरकारको सेनाले आफ्नो दरबार घेरा हालेको उसलाई थाहा भयो । तर त्यत्रो संख्यामा अत्याधुनिक हतियारसहित आएको सेनासँग प्रतिकार गर्ने आफूसँग साधन थिएन । तर डम्बरध्वोज धेरै चतुर थिए, उनले आफ्नो दरबारभित्रैबाट तुरुन्त एउटा साडी पटुकी चौबन्दी चोली, ढुङ्ग्री मुन्द्री टाउकोमा सल बाँधी डोकामा खाली गाग्री बोकेर एकजना नवदुलही बुहारीका भेषभुषामा त्यत्रो सेनाको बिचबाट धारामा पानी भर्ने बहाना गरी निस्केर गए । सेनालाई कुनै अत्तोपत्तो भएन ।</p>\n<p>डम्बरध्वोज आफ्नो चोली डोको गाग्री एकातिर राखी छोडेर एक किलोमिटर माथि वारुम्मा देवीथानमा गई बसे र त्यहाँबाट एकजना मान्छे पठाई सेनाको क्याप्टेनलाई झिकाए । यो घटना अकल्पनीय र बडो आश्चर्यको कुरा छ । ताकी यसै घटनाले डम्बरध्वोज लिबाङको एउटा दैवी शक्ति र पराक्रमी व्यक्ति भएको पुष्टि गर्दछ । दुश्मनको टाउका काटेर लानलाई आएको सेनाको क्याप्टेन एउटा खबरको भरमा एक किलोमिटर माथि वारोम्मा भन्ने देवीथानमा लुरुलुरु हिँडेर गए र डम्बरध्वोजसँग भेट भयो । त्यसपछि वार्तालाप भयो । वार्तालाप भएको कुराकानी यस्तो थियो ।</p>\n<p>डम्बरध्वोज ः तपाईं सेनाको क्याप्टेन हुनुहुन्छ ? सेनाको क्याप्टेन ः हो हजुर ! डम्बरध्वोजः तपाईंलाई डम्बरध्वोज लिबाङको टाउको लिएर आउनु भन्ने आदेश छ होइन ? सेनाको क्याप्टेन ः हो टाउको लिएर आउनु भन्ने आदेश छ । डम्बरध्वोजः ए त्यसो भए डम्बरध्वोज लिबाङ भनेको मै हुँ । तपाईंलाई मेरो टाउको लानुको कुनै औचित्य छैन । अहिले तपाईं हामी पवित्र देवस्थलमा छौं । त्यसकारण आजको दिनदेखि तपाईं हामीले देवी देवतालाई साक्षी राखेर आजदेखि मित भयौं । हाम्रो मित्रता सदैव सुमधुर रहोस् भनी त्यहीँ देवीथानमा मित लगाएका थिए । त्यसबेला उनीहरूबीचको दुई बुँदे सम्झौता यस्तो थियो । १. ५२ ढोके दरबारको ढोका र झ्याल एउटा, एउटा बन्द गर्ने । २. शिर छेदन अर्थात टाउको काटेर ल््याउनु भनिएको डम्बरध्वोज लिबाङको दरबारमा घेरा हाली छापा मार्दा उसलाई नभेटिएको भन्ने श्री ३ सरकारलाई व्यहोरा जनाउने भन्ने शर्त राखी त्यसबेला डम्बरध्वोज लिबाङले उसको मित सेना क्याप्टेनलाई बाटो खर्च स्वरूप रु १६०० (दुइ पाथी मोहर) दिएर उनीहरू बिदा भए ।</p>\n<p> डम्बरध्वोज लिबाङको दरबारमा काम गर्नेहरु</p>\n<p>सभ्य मानव समाजमा असल कुराको मात्र गुनगान गरेर इतिहास सवल हुँदैन । मानिसभित्र गुण अवगुण अर्थात राम्रा नराम्रा कुराहरू अवश्य हुन्छन् । त्यसकायथार्थता इतिहासकार वा लेखकले कन्जुस्याईं गर्नुहुँदैन । त्यसैको ज्वलन्त उदाहरण हो डम्बरध्वोज लिबाङ । सत्य साँच्चिकै सत्य हुनेछ । झुट लेखे एक दिन झुट नै सावित हुनेछ । ५२ ढोका दरबारभित्र काम गर्ने कामदार र छोरी, चेली, बुहारीहरू विहानको खाना सक्नलाई बेलुकीसम्म हुन्थ्यो, अनि बेलुकीको खाना खुवाउनलाई बिहानीको भालेको डाकमा मात्र काम सक्थ्यो । त्यसैले त्यस दरबारभित्र काम गर्नेको दिकदार र हैरानी वर्णन गरेर साध्य थिएन । डम्बरध्वोज लिबाङको शारीरिक बनावट एउटा सानो कद अर्थात सानो जिउडालका थिए । त्यसैले उनको नाम सिङजेक भन्ने गरिन्थ्यो । सिङजेकको अर्थ एउटा सानो काठको सिन्का साँच्ची नै सानो र सिकुटे मानिस भएकोले त्यसो भनेको हुन सक्छ । तर उनको आँखा यस्तो तेज र अद्भूत थियो । जो परेवाको आँखा जस्तो सानो र तिरिरी घुमीरहने । र उनलाई जो कसैले सिधा नजर हेर्न सक्दैनथ्यो ।</p>\n<p> डम्बरध्वोज लिबाङलाई विष खुवाएर मार्ने षडयन्त्र</p>\n<p>&nbsp;डम्बरध्वोज लिबाङमा दुई ओटा विशेषता थियो । एक नम्बरमा ऊसित सद्भाव राख्ने मानिससँग मैत्रीपूर्ण व्यवहार गर्थे, तर उनको विरुद्धमा लाग्ने विरोधीहरूलाई चाहिँ पत्तासाफ गरेर छाड्थे । तथापि एकोहोरो शासनप्रणाली भित्र कुनै न कुनै मान्छे विरोधी हुन सक्छ । त्यसमाथि पनि आफ्नै दाजुभाई, एउटा पौराणिक भनाइ छ । बाघको अनुहार हेर्ने इच्छा भए, विरालोको अनुहार हेर्नु आफूलाई शत्रुको अनुहार हेर्न रहर भए, दाजुभाइकै अनुहार हेर्नु अरे, यो भनाइ कतिसम्म जायज होला उसैको विरुद्धमा आफ्नो काकाको छोरा रनहाङ लिबाङ भित्रभित्रै डम्बरध्वोज लिबाङलाई सिध्याउनको लागि एकजना कार्की घरका मान्छे प्रयोग गरेको डम्बरध्वोजको भान्से थियो । त्यो भान्सेले रनहाङले सिकाएर खानामा विष मिलाएर खाना राखिदिए । तर त्यो भान्से डम्बरध्वोजको छेउमा पुग्ने बित्तिकै थरर काम्छे त्यसरी कामेको देखेर शंका लागि सोधपुछ गर्ने क्रममा रनहाङले विष हालेर दिनु भनेको कुरा खोले । यो कुरा सार्वजनिक भएपछि रनहाङ भागेर आसाम गए । रनहाङ भागेपछि उनको मृत्यु आसाममै भयो । यता विष खुवाउन लगाइएका कार्की सोझा भएका कारण डम्बरध्वोजले उनलाई आम माफी दिए । त्यही क्रियाकलापबाट पनि बुझ्न सकिन्छ कि डम्बरध्वोज एउटा प्रतापी र उदारवादी शासक थिए । उनले २००७ सालमा पहाडबाट क्षेत्री बाहुन खेदाऊ अभियानमा पनि हामी सबै एकै हौं भनेर उनले त्यो कार्य रोक लगाएको थियो । हामी सबै जाति एक हौं, जातीय सद्भाव कायम राखौं भन्ने उहाँको महान सोच थियो ।</p>\n<p> ५२ ढोके दरबारमा आगलागी</p>\n<p>समयको कालखण्डसँगै हाम्रो देश नेपालमा त्यस्तो महत्वपूर्ण दरबारहरू आगलागी भएर जलेर गएको इतिहास हेर्न पाउँछौं । जस्तो काठमाडौंको सिंहदरबार जलेर जानुमा विभिन्न राजनीतिक कारणहरू थिए । तर लिबाङको ५२ ढोके दरबार जल्नुमा कुनै राजनैतिक कारण थिएन । वि.स. १९८० को फाल्गुण/चैतको सुख्खा खडेरीसँगै भयंकर आगोको ज्वाला दरबारमा पर्&zwj;यो । रंग रोगन इलामेल जस्ता रंगले सिँगारिएको दरबार दनदनी जल्न थाल्यो । डम्बरध्वोज लिबाङ दरबारको मुनि तलाको पूर्वी कोठामा सुतिरहेको थिएछ । दरबारभन्दा केही माथितिर उसको माइला भाइ महाधोजको घर थियो ।</p>\n<p>त्यस्तो दरबार जलिरहेको देखेर कुदी आएर आफ्नो दाजुलाई उठाए । डम्बरध्वोज जुरुक्कै उठेर हेर्दा आरती दरबार दनदनी जलिरहेको देखेर उनको गहभरि आँसुले पुरेछ तथापि उसको जीवनमा सबैभन्दा दुःखको विषय नै त्यहीँ थियो । त्यो दरबार के कारणले जल्यो यो अहिलेसम्म रहस्यमय नै रहेको छ ।</p>\n<p> डम्बरध्वज लिबाङ चढ्ने सेती घोडा&nbsp;</p>\n<p>&nbsp;डम्बरध्वोज लिबाङको समयमा कुनै यातायातको व्यवस्था थिएन । त्यस्तो विकट ठाउँ लिबाङमा ५२ ढोके दरबार बनाउँन चानचुने विषय थिएन । डम्बरध्वोज आफू सवार हुँदा उनी जहिल्यै घोडामा हुन्थ्यो र कुनै अप्ठ्यारो ठाउँमा चाहिँ र आफ्ना सिपाही प्रयोग गरेर उसलाई बोकेर लैजान्थे । उनी जहाँ सवारी हुँदा ४०&ndash;५० जना आफ्नो फौज सिपाही अघिपछि हिँडाउँथे । उनको घोडाको नाम सेती धोज थियो । माउ घोडा निक्खुर सेतो रंगको आकर्षक हस्टपुष्ट बलिया घोडा फुर्सदमा लिबाङ गाउँमा स्वतन्त्रपूर्वक चरनमा जान्थे र डम्बरध्वोज कहीँ कतै सवार हुनु पर्दा त्यस सेती घोडालाई खोज्नु पर्दैनथ्यो । दरबारमा एउटा घण्टी राखिएको थियो, त्यो घण्टी बेस्सरी हल्लाएपछि त्यस घण्टीको आवाज सुनेर सेती घोडा आफैं दौडेर आउँथे र डम्बरधोज चढेर जाने गथ्र्यो ।</p>\n<p>&nbsp;वि.स. २००९ सालमा डम्बरध्वोजको मृत्यु भयो । उनको मृत्युले परिवार गहिरो शोकमा डुबे । त्योभन्दा पनि धेरै शोक सेती घोडालाई पर्&zwj;यो । सेती घोडा विक्षिप्त अवस्थामा थिइन् । उनको आँखामा बलिन्द्र आँशुको धारा बगिरहेको थियो । बेस्सरी चिच्याएर भुइँमा लडीबडी गरिरहन्थ्यो । त्यो क्रम र अवस्था धेरै दिनसम्म चलिरहयो । सेती घोडाले क्रमशः दानापानी घाँस इत्यादि खानेकुराहरू छोड्दै गयो । त्यसपछि उनलाई कसैले पनि चढ्दैनथे र विस्तारै सेती घोडा पनि कमजोर हुँदै गई । आफ्नो मालिकको अनुपस्थिति र वियोगान्त व्यथाले शिथिल भई उदास र निराश भएकी सेती घोडाको पनि वि.स. २०१० सालमा मृत्यु भयो । मृत्युपश्चात लिबाङको साजु धाराको छेउमा गाडेर त्यस घोडाको पनि भव्यताको साथ दाहसंस्कार गरेको त्यसबेलाका जानकारले बताउने गर्छन् । समाप्त</p>',0,0,'published','2026-01-01 13:16:04','2026-01-01 13:10:19','2026-01-01 13:16:04',NULL),
